-- Catálogo de cámaras, Tanda 5 (Diego, 20-nov: «Aprobado»): Kiev, FED, LOMO,
-- Fujica, Agfa, gran formato y cine.
--
-- 135 modelos:
-- · 31 cámaras de cine Super 8 y 16 mm del museo oficial de Canon, con año;
-- · el resto, una lista curada por línea, con año solo donde Wikidata lo da.
-- Las de 8 mm normal, Single 8 y Doble Super 8 no entran: esos formatos no
-- están en el vocabulario. Revisión: docs privados, TANDA-5. Por clave: nunca
-- duplica ni pisa lo corregido desde el panel.

insert into public.camera_models
  (manufacturer_id, name, type, format, frame_sizes, mount_id, interchangeable, year_from,
   source, source_ref, status)
